def agency_agents() -> List[Dict[str, Any]]:
    """返回引入的 agency 预置 Agent（每条补默认 enabled=True，浅拷贝防调用方改坏源）。"""
    out: List[Dict[str, Any]] = []
    for a in AGENCY_AGENTS:
        item = dict(a)
        item.setdefault("enabled", True)
        item.setdefault("skill_slugs", [])
        out.append(item)
    return out
